-- LOB viewer samples (Postgres counterpart to source/V3__lob_samples.sql): one row per format the query view can render, for
-- checking previews by hand. Identical on both sides; nothing else depends on it.
-- The HTML and SVG rows embed scripts on purpose, to check the preview sandbox.

CREATE TABLE lob_samples (
    sample_id integer      NOT NULL,
    format    varchar(20)  NOT NULL,
    body      text,
    payload   bytea,
    CONSTRAINT pk_lob_samples PRIMARY KEY (sample_id)
);

INSERT INTO lob_samples (sample_id, format, body, payload)
VALUES (1, 'png', NULL,
        decode('', 'hex'));

